static const std::size_t kCount = sizeof(kActivation)/sizeof(kActivation[0]);
inline const Activation* Find(const char* code) {
    if(!code || !*code)return nullptr;
    std::size_t lo=0,hi=kCount;
    while(lo<hi) {const std::size_t m=lo+(hi-lo)/2;
        const int c=std::strcmp(kActivation[m].code,code);
        if(c<0)lo=m+1;else hi=m;
    }
    return lo<kCount && !std::strcmp(kActivation[lo].code,code) ? &kActivation[lo] : nullptr;
}
inline std::size_t EnabledCount() {std::size_t n=0;for(std::size_t i=0;i<kCount;++i)if(kActivation[i].jsonEnabled)++n;return n;}
inline std::size_t ConfiguredCount() {std::size_t n=0;for(std::size_t i=0;i<kCount;++i)if(kActivation[i].complete)++n;return n;}
inline bool RuntimeCanGrant(const char*) {return false;} // fail closed: no DAT commit adapter
